// e2e/offlineColdStart.spec.js
//
// Milestone 0.5.11 — Offline cold-start verification.
//
// Verifies that after the service worker (dist/service-worker.js, generated by
// scripts/inject-sw.cjs during `npm run build`) is installed and has
// pre-cached the app shell:
//   1. The SW is registered/active and Cache Storage contains app-shell
//      entries.
//   2. Going offline and reloading the page still loads the app shell from
//      the SW cache (the navigation is served by the SW, not the network).
//   3. localStorage ("tabsData") is intact and the previously-created note
//      is restored into the editor.
//
// [Clarification C — cold-start simulation technique]
//
// Chosen technique: a SINGLE browser context, closing the online page and
// opening a brand-new page in the same context (option 2 of the two offered).
//
// Why not chromium.launchPersistentContext(tempDir):
//   - Playwright treats a persistent userDataDir as its own profile, but SW
//     Cache Storage + localStorage persistence across relaunches is timing
//     dependent and awkward to reason about. A single context shares the
//     origin's Cache Storage and localStorage deterministically.
//   - Closing the online page and opening a fresh page gives us a real cold
//     navigation: no bfcache, no in-flight requests, no in-memory app state —
//     only the origin-scoped SW cache survives, which is exactly what a cold
//     start from a previously-installed SW exercises.
//
// [Why this spec starts its own server]
//
// The SW's ASSET_URLS list is built by crawling dist/, so the test must run
// against a server that serves those exact production files (the `astro dev`
// server does not). Rather than depend on a special Playwright project, the
// spec starts a tiny Node-stdlib static file server over dist/ on an
// ephemeral 127.0.0.1 port in beforeAll. 127.0.0.1 is a secure context, so
// service workers are allowed.
//
// Chromium-only: Cache Storage inspection and SW semantics are only asserted
// for Chromium (matches the existing offlinePreloading.spec.js convention).
//
// Run: npm run build && npx playwright test e2e/offlineColdStart.spec.js
// (the test self-skips if dist/service-worker.js is absent).

import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { test, expect } from "@playwright/test";
import { waitForAppReady, typeInEditor } from "./helpers.js";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const DIST_DIR = path.resolve(HERE, "..", "dist");
const SW_PATH = path.join(DIST_DIR, "service-worker.js");
const HAS_DIST_SW = fs.existsSync(SW_PATH);

const MIME = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "application/javascript; charset=utf-8",
  ".mjs": "application/javascript; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".webmanifest": "application/manifest+json",
  ".svg": "image/svg+xml",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".webp": "image/webp",
  ".ico": "image/x-icon",
  ".xml": "application/xml",
  ".txt": "text/plain; charset=utf-8",
  ".woff": "font/woff",
  ".woff2": "font/woff2",
};

let server = null;
let baseURL = "";

test.beforeAll(async () => {
  if (!HAS_DIST_SW) return;
  server = http.createServer((req, res) => {
    let pathname;
    try {
      pathname = decodeURIComponent(new URL(req.url, "http://localhost").pathname);
    } catch {
      res.writeHead(400);
      res.end("Bad request");
      return;
    }
    if (pathname === "/") pathname = "/index.html";
    const filePath = path.join(DIST_DIR, pathname);
    // Reject path traversal outside dist/.
    if (!filePath.startsWith(DIST_DIR)) {
      res.writeHead(403);
      res.end("Forbidden");
      return;
    }
    fs.readFile(filePath, (err, data) => {
      if (err) {
        res.writeHead(404);
        res.end("Not found");
        return;
      }
      res.writeHead(200, {
        "Content-Type":
          MIME[path.extname(filePath).toLowerCase()] || "application/octet-stream",
      });
      res.end(data);
    });
  });
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  const { port } = server.address();
  baseURL = `http://127.0.0.1:${port}`;
});

test.afterAll(async () => {
  if (server) {
    await new Promise((resolve) => server.close(resolve));
    server = null;
  }
});

// Chromium only — SW/Cache Storage assertions are Chromium-scoped here.
test.skip(({ browserName }) => browserName !== "chromium", "SW cold-start test: chromium only");

// Needs a production build so the SW's pre-cache list matches served files.
test.skip(!HAS_DIST_SW, "dist/service-worker.js not found — run `npm run build` first");

/** Wait until the service worker is active and controlling the page. */
function waitForSwActivation(page, timeoutMs = 30_000) {
  return page.evaluate(async (tMs) => {
    if (navigator.serviceWorker.controller) {
      return { ready: true, scriptURL: navigator.serviceWorker.controller.scriptURL };
    }
    const deadline = Date.now() + tMs;
    while (Date.now() < deadline) {
      if (navigator.serviceWorker.controller) {
        return { ready: true, scriptURL: navigator.serviceWorker.controller.scriptURL };
      }
      try {
        const reg = await navigator.serviceWorker.ready;
        if (reg.active) {
          return { ready: true, scriptURL: reg.active.scriptURL };
        }
      } catch {
        /* keep polling */
      }
      await new Promise((r) => setTimeout(r, 100));
    }
    return { ready: false, error: `SW not active within ${tMs}ms` };
  }, timeoutMs);
}

/** Wait until the SW's install handler has populated Cache Storage. */
function waitForSwPreCache(page, timeoutMs = 30_000) {
  return page.evaluate(async (tMs) => {
    const deadline = Date.now() + tMs;
    let lastSeen = { cacheName: null, entryCount: 0 };
    while (Date.now() < deadline) {
      for (const name of await caches.keys()) {
        const cache = await caches.open(name);
        const keys = await cache.keys();
        lastSeen = { cacheName: name, entryCount: keys.length };
        if (keys.length > 0) {
          return { ready: true, cacheName: name, entryCount: keys.length };
        }
      }
      await new Promise((r) => setTimeout(r, 100));
    }
    return { ready: false, ...lastSeen, error: "SW pre-cache did not populate" };
  }, timeoutMs);
}

/** Read the persisted tab list and report whether the note text is present. */
function readStoredNotes(page, needle) {
  return page.evaluate((text) => {
    let data = [];
    try {
      data = JSON.parse(localStorage.getItem("tabsData") || "[]");
    } catch {
      data = [];
    }
    const serialized = JSON.stringify(data);
    return { notePresent: serialized.includes(text), tabCount: data.length };
  }, needle);
}

test.describe("Milestone 0.5.11 — offline cold start from SW cache", () => {
  test.describe.configure({ timeout: 120_000 });

  test("SW pre-caches the shell online, then an offline cold start loads the shell and restores the note", async ({ context, page }) => {
    const noteText = "offline-cold-start-note";

    // ---- Phase 1: online install + note creation -------------------------
    await page.goto(`${baseURL}/`);
    await waitForAppReady(page);

    const activation = await waitForSwActivation(page);
    expect(activation.ready, JSON.stringify(activation)).toBe(true);

    const preCache = await waitForSwPreCache(page);
    expect(preCache.ready, JSON.stringify(preCache)).toBe(true);
    expect(preCache.entryCount).toBeGreaterThan(0);

    // A fresh context starts with zero tabs, so waitForAppReady has already
    // created exactly one. Type into it so the restored tab is unambiguous.
    await typeInEditor(page, noteText);
    await page.waitForTimeout(800);

    const storedBefore = await readStoredNotes(page, noteText);
    expect(storedBefore.notePresent).toBe(true);

    // ---- Phase 2: cold start (new page, same context) --------------------
    await page.close();
    const coldPage = await context.newPage();
    await coldPage.goto(`${baseURL}/`);
    await waitForAppReady(coldPage);
    expect(
      await coldPage.evaluate(() => !!navigator.serviceWorker.controller)
    ).toBe(true);

    // ---- Phase 3: go offline and reload ----------------------------------
    await context.setOffline(true);
    await coldPage.reload({ waitUntil: "load" });
    await waitForAppReady(coldPage);

    // The app shell must be usable while offline.
    await expect(coldPage.locator("#create-tab")).toBeVisible({ timeout: 15_000 });

    // localStorage survived the offline cold start.
    const storedAfter = await readStoredNotes(coldPage, noteText);
    expect(storedAfter.notePresent).toBe(true);
    expect(storedAfter.tabCount).toBeGreaterThan(0);

    // The note is rendered back into the editor.
    await expect(coldPage.locator(".ProseMirror").last()).toContainText(noteText, {
      timeout: 20_000,
    });

    await context.setOffline(false);
  });

  test("a note created while offline is persisted and survives a reload", async ({ context, page }) => {
    const noteText = "created-while-offline";

    await page.goto(`${baseURL}/`);
    await waitForAppReady(page);
    const activation = await waitForSwActivation(page);
    expect(activation.ready, JSON.stringify(activation)).toBe(true);
    const preCache = await waitForSwPreCache(page);
    expect(preCache.ready, JSON.stringify(preCache)).toBe(true);

    // Cold page in the same context, then go offline.
    await page.close();
    const offlinePage = await context.newPage();
    await offlinePage.goto(`${baseURL}/`);
    await waitForAppReady(offlinePage);
    expect(
      await offlinePage.evaluate(() => !!navigator.serviceWorker.controller)
    ).toBe(true);

    await context.setOffline(true);
    await offlinePage.reload({ waitUntil: "load" });
    await waitForAppReady(offlinePage);

    // Edit while offline.
    await typeInEditor(offlinePage, noteText);
    await offlinePage.waitForTimeout(800);
    expect((await readStoredNotes(offlinePage, noteText)).notePresent).toBe(true);

    // Reload while still offline — content must come from localStorage.
    await offlinePage.reload({ waitUntil: "load" });
    await waitForAppReady(offlinePage);
    await expect(offlinePage.locator(".ProseMirror").last()).toContainText(noteText, {
      timeout: 20_000,
    });

    await context.setOffline(false);
  });
});
